INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (21, "", "", 0, "vo_asb", "vo_asb_0723", "", "", 0, 72, 72020);
INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (11, 0, 0, 1, 1, "だからわたし、\n勇気を出して言ってみたんです！\nお友だちになりませんか、って。", 0, 1, 10, 72, 72021);
INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (91, "", "", 0, 0, "", "", "", 0, 72, 72022);
