INSERT INTO `v1_42461f68abc336e7d6c58dec840969fec1bc77983a5766f50230de57d97eb6d7` VALUES (11, 0, 0, 1, 1, "暗くて、狭くて。\n涼しくて、静かで。\nなんとなく、落ち着く……というか。", 0, 1, 10, 92, 92015);
